# Trading phases (Eastern Time, converted to Central = ET - 1 hour)
# Phase boundaries in minutes from midnight (CT)
class TradingPhase(Enum):
    """Trading day phases with different risk profiles."""

    PREMARKET = "premarket"  # Before market open
    OBSERVATION = "observation"  # 9:30-9:45 ET = 8:30-8:45 CT - Watch only (configurable via observation_period_minutes)
    RESEARCH = "research"  # 9:45-10:30 ET = 8:45-9:30 CT - Validate signals (observation_period_minutes after open)
    CORE_TRADING = "core_trading"  # 10:30-15:00 ET = 9:30-14:00 CT - Full trading
    WIND_DOWN = "wind_down"  # 15:00-16:00 ET = 14:00-15:00 CT - No new entries
    AFTER_HOURS = "after_hours"  # After market close


# Phase time windows in CT (minutes from midnight)
# Note: PHASE_RESEARCH_START default is 8:45 CT = 9:45 ET (15 min observation)
PHASE_OBSERVATION_START = 8 * 60 + 30  # 8:30 CT = 9:30 ET
PHASE_RESEARCH_START = (
    8 * 60 + 45
)  # 8:45 CT = 9:45 ET (default; overridden dynamically where needed)
PHASE_CORE_START = 9 * 60 + 30  # 9:30 CT = 10:30 ET
PHASE_WINDDOWN_START = 14 * 60  # 14:00 CT = 15:00 ET
PHASE_MARKET_CLOSE = 15 * 60  # 15:00 CT = 16:00 ET

# Retry configuration
MAX_RETRIES = 3
RETRY_DELAY = 5  # seconds
HEARTBEAT_INTERVAL = 300  # Log heartbeat every 5 minutes


def retry_on_error(max_retries=MAX_RETRIES, delay=RETRY_DELAY):
    """Decorator for retrying functions on error."""

    def decorator(func):
        def wrapper(*args, **kwargs):
            last_error = None
            for attempt in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    last_error = e
                    if attempt < max_retries - 1:
                        logger.warning(
                            f"{func.__name__} failed (attempt {attempt + 1}/{max_retries}): {e}"
                        )
                        time.sleep(delay * (attempt + 1))  # Exponential backoff
                    else:
                        logger.error(
                            f"{func.__name__} failed after {max_retries} attempts: {e}"
                        )
            raise last_error

        return wrapper

    return decorator


class DayManager:
    """Active position manager for day trading."""

    def __init__(self, dry_run: bool = True):
        self._boot_started_perf = time.perf_counter()
        self._boot_last_perf = self._boot_started_perf
        self._boot_timing: List[Dict[str, Any]] = []
        self.dry_run = dry_run
        creds = resolve_alpaca_credentials(require=True)
        self.api_key = creds.api_key
        self.secret_key = creds.secret_key
        self.paper = bool(creds.paper)
        self.config = CONFIG
        self.trim_governance_cfg = getattr(CONFIG, "trim_governance", SimpleNamespace())
        self.llm_advisory_escalation_cfg = getattr(
            CONFIG, "llm_advisory_escalation", SimpleNamespace()
        )
        self.loss_floor_cfg = getattr(CONFIG, "loss_floor", SimpleNamespace())
        self.overnight_cut_policy_cfg = getattr(
            CONFIG, "overnight_cut_policy", SimpleNamespace()
        )
        self.plan_caps_cfg = getattr(CONFIG, "plan_caps", SimpleNamespace())
        self._session_state = RuntimeSessionStateStore(
            Path(CONFIG.project_root) / "data" / "runtime_session_state.json"
        )

        self.MIN_TRIM_NOTIONAL = 400.0  # Minimum $ value for a non-exit trim
        self.MIN_TRIM_QTY_PCT = 0.10  # Minimum 10% of position for a trim
        # Bumped 60 -> 240 after live audit on 2026-05-07 showed EOSE
        # being trimmed 5x in 30 minutes due to LangGraph fallback
        # decisions all returning TRIM with score=-25 reasoning=
        # "fallback:cooldown_or_budget". Wider cooldown lets a position
        # breathe through one round of fallback noise.
        self.TRIM_COOLDOWN_MINUTES = int(
            os.environ.get(
                "AUTOTRADE_TRIM_COOLDOWN_MINUTES",
                str(getattr(self.trim_governance_cfg, "cooldown_minutes", 240)),
            )
        )
        self.MAX_TRIMS_PER_SYMBOL_PER_DAY = int(
            getattr(self.trim_governance_cfg, "max_per_symbol_per_day", 2) or 2
        )

        self.MIN_ADD_NOTIONAL = 500.0  # Minimum $ value for a position addition
        self.ADD_COOLDOWN_MINUTES = 15  # Minimum minutes between adds on same symbol
        self.ADD_PNL_STEP = 1.0  # Must gain additional 1% since last add to scale more

        # Initialize API clients with retry
        self.client = None
        self.data_client = None
        self._init_clients()
        self._record_boot_step("clients")

        # Import helpers
        from autotrade.risk.day_trade_tracker import DayTradeTracker
        import autotrade.signals.trade_learner as trade_learner
        from autotrade.analysis.execution_quality_tracker import ExecutionQualityTracker
        from autotrade.utils.execution_logger import OrderLifecycleLogger
        from autotrade.execution.local_exit_manager import LocalExitManager

        self.eq_tracker = ExecutionQualityTracker()
        self.lifecycle_logger = OrderLifecycleLogger()
        self.exit_manager = LocalExitManager()

        self.day_tracker = DayTradeTracker()
        self.trade_journal = trade_learner.get_journal()
        self.lesson_book = trade_learner.get_lesson_book()
        self._record_boot_step("core_helpers")

        # Initialize unified strategy (multi-level approach from backtest)
        # Backtested: +52% better P&L, +51% better avg trade, PF 1.66
        from autotrade.signals.unified_strategy import UnifiedStrategy, MIN_LESSON_SCORE
        from autotrade.signals.conviction_engine import ConvictionEngine
        from autotrade.risk.strategy_failsafe import StrategyFailsafeManager

        self.strategy = UnifiedStrategy(min_score=MIN_LESSON_SCORE)
        self.conviction_engine = ConvictionEngine()
        self.strategy_failsafe = StrategyFailsafeManager()
        self.strategy_failsafe_snapshot = self.strategy_failsafe.load_snapshot()
        self._positions_from_cache = False
        self._external_exclusion_list: Set[str] = set()

        # Initialize R-Unit Risk Sizer (Volatility-adjusted sizing)
        try:
            # Try to get starting equity for sizing, default to 100k if unavailable
            start_eq = float(
                getattr(self.strategy_failsafe_snapshot, "current_equity", 100000.0)
            )
            self.r_unit_sizer = RUnitSizer(
                total_equity=start_eq,
                risk_pct=0.01,  # 1% risk per trade
                max_notional_pct=0.05,  # max 5% notional per trade
            )
            logger.info(
                f"R-Unit Sizer initialized (Risk: 1%, Max Notional: 5%, Baseline: ${start_eq:,.0f})"
            )
        except Exception as e:
            logger.warning(f"Could not initialize R-Unit Sizer: {e}")
            self.r_unit_sizer = None

        logger.info(f"Unified Strategy loaded (min_score={MIN_LESSON_SCORE})")
        logger.info(
            f"[FAILSAFE] Loaded: level={self.strategy_failsafe_snapshot.level.upper()} "
            f"halt_entries={self.strategy_failsafe_snapshot.halt_new_entries} "
            f"max_positions={self.strategy_failsafe_snapshot.max_positions}"
        )
        self._record_boot_step("strategy_failsafe")

        # Initialize intelligent position advisor
        # Try AgenticAdvisor first (multi-agent LangGraph workflow), fall back to legacy PositionAdvisor
        self.position_advisor = None
        self.use_agentic = False

        try:
            from autotrade.core.agentic_advisor import AgenticAdvisor

            self.position_advisor = AgenticAdvisor(
                trading_client=None,
                dry_run=True,
                allow_workflow_execution=False,
            )
            self.use_agentic = True
            logger.info(
                "Agentic Advisor (multi-agent workflow, advisory-only) initialized"
            )
        except Exception as e:
            logger.warning(f"Could not initialize Agentic Advisor: {e}")
            # Fall back to legacy PositionAdvisor
            try:
                from autotrade.advisors.position_advisor import PositionAdvisor

                self.position_advisor = PositionAdvisor()
                logger.info("Position Advisor (legacy LLM) initialized")
            except Exception as e2:
                logger.warning(f"Could not initialize Position Advisor: {e2}")
                self.position_advisor = None
        self._record_boot_step("position_advisor")

        self.entry_quality_cfg = CONFIG.entry_quality
        self.risk_gate_cfg = CONFIG.risk_gate
        self.execution_entry_cfg = getattr(
            getattr(CONFIG, "execution", SimpleNamespace()),
            "entry",
            SimpleNamespace(),
        )
        self.advisor_control_cfg = getattr(
            CONFIG,
            "advisor_control",
            SimpleNamespace(),
        )
        self.research_freshness_cfg = CONFIG.research_freshness
        self.signal_validation_cfg = CONFIG.signal_validation
        self.feature_engineering_cfg = CONFIG.feature_engineering
        self.posture_cfg = getattr(CONFIG, "posture", SimpleNamespace())
        self.signal_generation_cfg = CONFIG.signal_generation
        self.data_gateway_active = False
        self._add_block_after_trim = bool(
            getattr(self.risk_gate_cfg, "add_block_after_trim", True)
        )
        self._midday_revalidation_trim_fraction = float(
            getattr(self.risk_gate_cfg, "midday_revalidation_trim_fraction", 0.33)
        )
        self._min_hold_minutes_for_trim = int(
            getattr(self.risk_gate_cfg, "min_hold_minutes_for_trim", 120)
        )
        self._add_blocked_symbols_today: Set[str] = set(
            str(s).upper()
            for s in self._session_state.get("add_blocked_symbols_today", []) or []
            if str(s).strip()
        )
        self._hard_stop_blocked_symbols_today: Dict[str, datetime] = (
            self._normalize_hard_stop_blocked_symbols(
                self._session_state.get("hard_stop_blocked_symbols_today", {}) or {}
            )
        )
        self._last_market_posture_state: Dict[str, Any] = dict(
            self._session_state.get("market_posture_state", {}) or {}
        )
        self._exited_symbols_today: Set[str] = set(
            str(s).upper()
            for s in self._session_state.get("exited_symbols_today", []) or []
            if str(s).strip()
        )
        self._symbol_intent_state_today: Dict[str, Dict[str, Any]] = {}
        self._runtime_entry_blocked_symbols: Dict[str, Dict[str, Any]] = {}
        self._session_inactive_symbols: Set[str] = set()
        self._sublot_replacement_pending: Dict[str, Dict[str, Any]] = {}
        self._replacement_session_blacklist: Dict[str, Set[str]] = {}
        self._last_replacement_rejection: Dict[str, str] = {}
        self._recent_symbol_quarantine_days = 14
        self._recent_symbol_quarantine_losses = 2

        # Feature engineering pipeline (guarded, additive only).
        self.feature_pipeline = None
        self.feature_pipeline_active = False
        self._feature_cache: Dict[str, Dict[str, Any]] = {}
        self._feature_cache_updated_at: Optional[datetime] = None
        self._feature_cache_ttl = timedelta(
            minutes=max(
                1, int(getattr(self.feature_engineering_cfg, "cache_ttl_minutes", 60))
            )
        )
        self._feature_pipeline_health: Dict[str, Any] = {
            "status": "disabled",
            "cache_hit": False,
            "feature_count": 0,
            "symbol_count": 0,
            "last_error": None,
            "last_run": None,
            "retry_requested": False,
            "last_failure_phase": "",
            "_logged_market_open_failure": False,
        }
        if bool(getattr(self.feature_engineering_cfg, "enabled", True)):
            try:
                from autotrade.feature_engineering.pipeline import FeaturePipeline

                fe_cfg = self.feature_engineering_cfg.model_dump()
                self.feature_pipeline = FeaturePipeline(config=fe_cfg)
                self.feature_pipeline_active = True
                self._feature_pipeline_health["status"] = "initialized"
                logger.info("FeaturePipeline initialized")
            except Exception as e:
                self.feature_pipeline = None
                self.feature_pipeline_active = False
                self._feature_pipeline_health["status"] = "unavailable"
                self._feature_pipeline_health["last_error"] = str(e)
                logger.warning(
                    f"FeaturePipeline unavailable, using legacy factor hydration only: {e}"
                )
        self._record_boot_step("feature_pipeline")

        # DayManager signal pipeline (alpha-zoo enrichment for parsed signals).
        self.signal_pipeline = None
        self.alpha_zoo_active = False
        self.alpha_zoo_signal_count = 0
        self.last_alpha_zoo_run: Optional[str] = None
        if bool(
            getattr(self.signal_generation_cfg, "day_manager_pipeline_enabled", True)
        ):
            try:
                from autotrade.signals.pipeline import SignalGenerationPipeline

                self.signal_pipeline = SignalGenerationPipeline(parent_logger=logger)
                logger.info("DayManager SignalGenerationPipeline initialized")
            except Exception as e:
                self.signal_pipeline = None
                logger.warning(
                    f"DayManager signal pipeline unavailable, legacy parsing only: {e}"
                )
        self._record_boot_step("signal_pipeline")

        # Optional alpha-zoo regime router (complements quantitative regime detection).
        self.regime_router = None
        self.regime_router_active = False
        self.regime_router_context: Dict[str, Any] = {
            "regime": "neutral",
            "confidence": 0.0,
            "method": "disabled",
            "last_updated": None,
        }
        if bool(getattr(self.signal_generation_cfg, "enable_regime_router", True)):
            try:
                from autotrade.signals.regime_router import RegimeRouter

                self.regime_router = RegimeRouter(parent_logger=logger)
                self.regime_router_active = True
                self.regime_router_context["method"] = "router"
                logger.info("Alpha-zoo RegimeRouter initialized")
            except Exception as e:
                self.regime_router = None
                self.regime_router_active = False
                self.regime_router_context["method"] = "unavailable"
                logger.warning(
                    f"RegimeRouter unavailable, using quantitative/youtube regime only: {e}"
                )
        self._record_boot_step("regime_router")

        # Load today's signals.
        self._active_plan_path: Optional[Path] = None
        self._active_plan_payload: Dict[str, Any] = {}
        self._core_data_readiness: Dict[str, Any] = {}
        self.signals = self._load_signals()
        self._record_boot_step("load_signals")
        self.signal_status = self._init_signal_tracking(self.signals)
        self._initial_watchlist_tickers: Set[str] = {
            str(s.get("ticker") or s.get("symbol") or "").upper()
            for s in (self.signals or [])
            if str(s.get("ticker") or s.get("symbol") or "").strip()
        }
        self._watched_universe_tickers: Set[str] = set(self._initial_watchlist_tickers)
        self.momentum_scanner_cfg = getattr(CONFIG, "momentum_scanner", None)
        self._momentum_watchlist_state: Dict[str, Any] = {}
        self._intraday_reserved_symbols: Set[str] = set()
        # Cache today's session open price per symbol so the gap-gate can
        # re-anchor against the actual open instead of a stale overnight plan.
        # Keyed by symbol; value (date, open_price_float). Cleared on date change.
        self._session_open_cache: Dict[str, Tuple[date, float]] = {}
        # End-of-day review state. Tracks which symbols have already had which
        # EOD actions taken so the review is idempotent across cycles within the
        # 15:30-16:00 ET window.
        self._eod_review_session_date: Optional[date] = None
        self._eod_review_actions: Dict[str, Set[str]] = {}
        self._overnight_cut_session_date: Optional[date] = None
        self._overnight_cut_actions: Dict[str, Set[str]] = {}
        self._position_slot_class_by_symbol: Dict[str, str] = {}
        self._intraday_reserved_entries_today = 0
        self._intraday_reserved_last_scan_date: Optional[date] = None
        self._strength_reentry_state: Dict[str, Dict[str, Any]] = {}
        self._strength_reentry_entries_today = 0
        self._strength_reentry_adds_today = 0
